#!/usr/bin/env node
// Extracts the pure canvas-renderer slice from desktop/plugin.js into a
// CommonJS module that runs under node-canvas. Generated file is gitignored;
// regenerate before every media run so shots always match the shipped code.
const fs = require('fs')
const path = require('path')

const root = path.resolve(__dirname, '..', '..')
const source = fs.readFileSync(path.join(root, 'desktop', 'plugin.js'), 'utf8')

const startMarker = 'function orderedEntities(state) {'
const endMarker = 'function BlinkenCanvas('
const start = source.indexOf(startMarker)
const end = source.indexOf(endMarker)
if (start < 0 || end < 0 || end <= start) {
  console.error('renderer boundaries moved; update extract-renderer.js')
  process.exit(1)
}

let slice = source.slice(start, end)
// node-canvas does not know the CSS ui-monospace keyword; keep the real mono stack.
slice = slice.replace(
  /ui-monospace, SFMono-Regular, Consolas, monospace/g,
  'Menlo, "SF Mono", Consolas, monospace'
)

const shim = `// GENERATED by scripts/media/extract-renderer.js — do not edit.
'use strict'
const { createCanvas } = require('canvas')
globalThis.document = { createElement: () => createCanvas(1, 1) }
globalThis.host = {
  state: {
    activeSessionId: { get: () => 'demo-session' },
    profile: { get: () => 'default' }
  },
  notify: () => {}
}
globalThis.haptic = () => {}
const clamp = (value, min = 0, max = 1) => Math.max(min, Math.min(max, Number(value) || 0))
`

const exportsTail = `
module.exports = { drawMatrixBank, modePalette, MODES, PATTERNS, orderedEntities }
`

fs.writeFileSync(path.join(__dirname, 'renderer.generated.cjs'), shim + slice + exportsTail)
console.log('renderer.generated.cjs written:', end - start, 'chars sliced')
